boolean canMake(int[] a, int target) {
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;
    for (int x : a)
        for (int s = x; s <= target; s++)
            dp[s] |= dp[s - x];
    return dp[target];
}

int[] tails = new int[a.length];
int len = 0;
for (int x : a) {
    int lo = 0, hi = len;              // first tails[i] >= x
    while (lo < hi) {
        int mid = (lo + hi) >>> 1;
        if (tails[mid] < x) lo = mid + 1; else hi = mid;
    }
    tails[lo] = x;
    if (lo == len) len++;
}

